package com.petcare.backend.controller;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import com.petcare.backend.dto.common.PageResponse;import com.petcare.backend.dto.notification.response.NotificationResponse;import com.petcare.backend.security.UserPrincipal;import com.petcare.backend.service.NotificationService;import java.util.List;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.*;
@ExtendWith(MockitoExtension.class) @MockitoSettings(strictness=org.mockito.quality.Strictness.LENIENT) class NotificationControllerTest{@Mock NotificationService service;@Mock UserPrincipal principal;NotificationController c;@BeforeEach void init(){c=new NotificationController(service);when(principal.getId()).thenReturn(1L);}@Test void allMethodsDelegate(){var page=PageResponse.<NotificationResponse>builder().content(List.of()).build();var n=mock(NotificationResponse.class);when(service.getMyNotifications(1L,0,20)).thenReturn(page);when(service.countUnread(1L)).thenReturn(2L);when(service.markAsRead(1L,3L)).thenReturn(n);assertThat(c.getMyNotifications(principal,0,20).getBody().getData()).isSameAs(page);assertThat(c.countUnread(principal).getBody().getData()).isEqualTo(2L);assertThat(c.markAsRead(principal,3L).getBody().getData()).isSameAs(n);c.markAllAsRead(principal);verify(service).markAllAsRead(1L);}}
